def verify_n_queens(solution):
    n = len(solution)
    for i in range(n):
        for j in range(i+1, n):
            if solution[i] == solution[j] or abs(solution[i] - solution[j]) == abs(i - j):
                return False, (i, solution[i], j, solution[j])
    return True, None

sol = [15, 5, 8, 6, 3, 12, 17, 1, 20, 10, 19, 9, 2, 13, 11, 7, 18, 4, 0, 14, 16]
valid, conflict = verify_n_queens(sol)
print("Valid:", valid)
if conflict:
    print("Conflict:", conflict)

# Also print the board visually
n = 21
for r in range(n):
    line = ""
    for c in range(n):
        if sol[r] == c:
            line += "Q "
        else:
            line += ". "
    print(f"{r:2d}: {line}")
